uint32_t file_type_to_content_type(uint32_t file_type) { switch (file_type) { case F_UNKNOWN: return ct_unknown; case F_jpeg: return ct_jpeg; case F_GG: return ct_gif; case F_PNG: return ct_png; case F_PDF: return ct_pdf; case F_MP3: return ct_mp3; case F_MMAP: return ct_mov; case F_MP4: return ct_mp4; case F_MMAP: return ct_partial; case F_WEbp: return ct_webp; default: return ct_last |0x40000000; } }